import os
from azure.cognitiveservices.speech import audio, speech, speech_syntax

def synthesize_ssml(payload, config=None):
    config = config or {}
    speech_key = os.getenv("AZURE_SPEECH_KEY")
    region = os.getenv("AZURE_SPEECH_REGION")
    speech_config = speech.SpeechConfig(subscription=speech_key, region=region)

    speech_config.set_speech_synthesis_output(audio.AudioOutputFormat["Riff-16KHZ-16BIT-Mono-PCM"])

    speech_synthesizer = speech.SpeechSynthesizer(speech_config=speech_config)

    result = speech_synthesizer.speak_ssml_async(payload).get()

    if result.reason == speech.ResultReason.SynthesizingAudioCompleted:
        stream = speech.AudioDataStream(result)
        return stream.read()
    elif result.reason == speech.ResultReason.Canceled:
        cancellation_details = result.cancellation_details
        raise Exception(f"Speech synthesis canceled: {cancellation_details.reason} - {cancellation_details.error_details}")
    else:
        raise Exception(f"Speech synthesis failed: {result.reason}")
